(function(){'use strict';const api=window.CeylonExplorer,section=document.querySelector('#island-explorer');if(!api||!section)return;
const $=s=>section.querySelector(s),modal=document.querySelector('#explorer-detail-dialog'),key='ceylon-voyagers-explorer-v1';let active=api.places[0].id,category='all',wishlist=[],canStore=true,lastInquiry='';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
try{wishlist=api.cleanWishlist(JSON.parse(localStorage.getItem(key)||'[]'));}catch{canStore=false;}
function announce(s){$('.explorer-status').textContent=s;}
function save(){try{localStorage.setItem(key,JSON.stringify(wishlist));canStore=true;}catch{canStore=false;}$('.explorer-save-note').textContent=canStore?'Your wishlist is saved in this browser.':'Your wishlist is available for this visit. Browser saving is unavailable.';}
const ns='http://www.w3.org/2000/svg';function svg(tag,attrs){const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e;}
api.places.forEach(p=>{const [x,y]=api.project(p.coords),[lx,ly]=p.label;const line=svg('path',{d:`M${x},${y} L${lx},${ly}`,class:'explorer-leader','data-explorer-point':p.id});$('.explorer-point-lines').append(line);const group=svg('g',{'data-explorer-point':p.id,class:'explorer-dot-group'});group.append(svg('circle',{cx:x,cy:y,r:14,class:'explorer-dot-halo'}),svg('circle',{cx:x,cy:y,r:5,class:'explorer-dot'}));group.style.cursor='pointer';group.addEventListener('click',()=>{if(category==='all'||p.categories.includes(category))choose(p.id,true);});$('.explorer-point-dots').append(group);const button=document.createElement('button');button.type='button';button.className='explorer-marker';button.dataset.explorerPlace=p.id;button.style.left=lx/640*100+'%';button.style.top=ly/610*100+'%';button.setAttribute('aria-label','Explore '+p.name);button.setAttribute('aria-pressed','false');button.innerHTML='<span class="explorer-marker-name">'+esc(p.name)+'</span><span class="explorer-marker-saved" aria-hidden="true">✓</span>';button.onclick=()=>choose(p.id,true);$('.explorer-markers').append(button);});
function syncMap(){const matches=api.matching(category).map(p=>p.id);section.querySelectorAll('[data-explorer-point]').forEach(e=>{e.classList.toggle('selected',e.dataset.explorerPoint===active);e.classList.toggle('muted',!matches.includes(e.dataset.explorerPoint));e.classList.toggle('saved',wishlist.includes(e.dataset.explorerPoint));});section.querySelectorAll('[data-explorer-place]').forEach(b=>{const id=b.dataset.explorerPlace;b.hidden=!matches.includes(id);b.classList.toggle('selected',id===active);b.classList.toggle('saved',wishlist.includes(id));b.setAttribute('aria-pressed',String(id===active));b.setAttribute('aria-label','Explore '+api.places.find(p=>p.id===id).name+(wishlist.includes(id)?', saved to My Journey':''));});$('.explorer-match-count').textContent=matches.length+' '+(matches.length===1?'place':'places')+' to discover';}
function syncAdd(){const saved=wishlist.includes(active);$('.explorer-add').innerHTML=(saved?'Added to My Journey':'Add to My Journey')+' <span aria-hidden="true">'+(saved?'✓':'+')+'</span>';$('.explorer-add').setAttribute('aria-pressed',String(saved));$('.explorer-photo-save').setAttribute('aria-label',(saved?'Remove ':'Add ')+api.places.find(p=>p.id===active).name+(saved?' from':' to')+' My Journey');$('.explorer-photo-save').setAttribute('aria-pressed',String(saved));$('.explorer-photo-save').classList.toggle('saved',saved);}
function choose(id,user=false){active=id;const p=api.places.find(p=>p.id===id);const image=$('#explorer-place-image');image.alt=p.alt;image.src=p.image;$('.explorer-photo-index').textContent=String(api.places.indexOf(p)+1).padStart(2,'0')+' / '+String(api.places.length).padStart(2,'0');$('.explorer-place-region').textContent=p.region;$('#explorer-place-name').textContent=p.name;$('.explorer-place-description').textContent=p.description;$('.explorer-place-tags').replaceChildren(...p.categories.map(c=>{const e=document.createElement('span');e.textContent=c;return e;}));$('.explorer-place-attractions').replaceChildren(...p.attractions.map(text=>{const e=document.createElement('li');e.textContent=text;return e;}));let credit=$('.explorer-card-credit');if(!credit){credit=document.createElement('p');credit.className='explorer-card-credit';$('.explorer-place-copy').append(credit);}credit.hidden=!p.credit;if(p.credit)credit.innerHTML='Photo: <a href="https://commons.wikimedia.org/wiki/File:Galle_Fort,_Sri_Lanka.JPG" target="_blank" rel="noopener noreferrer">Grayswoodsurrey</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · resized.';const card=$('.explorer-destination');card.classList.remove('explorer-card-enter');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)requestAnimationFrame(()=>card.classList.add('explorer-card-enter'));syncMap();syncAdd();if(user){announce(p.name+' selected. Destination details are shown '+(matchMedia('(max-width:760px)').matches?'below the map.':'beside the map.'));if(matchMedia('(max-width:760px)').matches)card.scrollIntoView({behavior:motion(),block:'start'});}}
function renderWishlist(){const panel=$('.explorer-wishlist-places');panel.replaceChildren();if(!wishlist.length){const p=document.createElement('p');p.textContent='Save the places that speak to you. Your island story starts here.';panel.append(p);}else wishlist.forEach(id=>{const place=api.places.find(p=>p.id===id),chip=document.createElement('div');chip.className='explorer-wishlist-chip';const photo=document.createElement('img');photo.src=place.image;photo.alt='';photo.width=28;photo.height=28;const name=document.createElement('button');name.type='button';name.className='explorer-wishlist-name';name.textContent=place.name;name.setAttribute('aria-label','View saved destination '+place.name);name.onclick=()=>{if(category!=='all'&&!place.categories.includes(category))setFilter('all');choose(id,true);};const remove=document.createElement('button');remove.type='button';remove.className='explorer-wishlist-remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+place.name+' from My Journey');remove.onclick=()=>toggle(id,remove);chip.append(photo,name,remove);panel.append(chip);});$('.explorer-wishlist-count').textContent=wishlist.length+' '+(wishlist.length===1?'place':'places');$('.explorer-plan').disabled=!wishlist.length;$('.explorer-clear').hidden=!wishlist.length;syncMap();syncAdd();}
function toggle(id,trigger){const i=wishlist.indexOf(id);if(i<0)wishlist.push(id);else wishlist.splice(i,1);save();renderWishlist();syncDialogAdd();announce(api.places.find(p=>p.id===id).name+(i<0?' added to':' removed from')+' My Journey. '+wishlist.length+' saved.');if(trigger?.classList.contains('explorer-wishlist-remove')){$('.explorer-wishlist-remove')?.focus();if(!wishlist.length)$('.explorer-detail').focus();}}
function setFilter(value){category=value;section.querySelectorAll('[data-explorer-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.explorerFilter===category)));const matches=api.matching(category);if(!matches.some(p=>p.id===active))choose(matches[0].id);else syncMap();announce((category==='all'?'All interests':category)+': '+matches.length+' destinations. '+api.places.find(p=>p.id===active).name+' details shown.');}
section.querySelectorAll('[data-explorer-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.explorerFilter));const back=document.createElement('button');back.type='button';back.className='explorer-back-map';back.textContent='Back to the map ↑';back.onclick=()=>$('.explorer-map-side').scrollIntoView({behavior:motion(),block:'start'});$('.explorer-place-copy').append(back);$('.explorer-add').onclick=()=>toggle(active);$('.explorer-photo-save').onclick=()=>toggle(active);$('.explorer-clear').onclick=()=>{wishlist=[];save();renderWishlist();announce('My Journey cleared.');$('.explorer-detail').focus();};
$('.explorer-plan').onclick=()=>{if(!wishlist.length)return;const field=document.querySelector('#inquiry textarea[name="message"]');if(!field){announce('The enquiry form is currently unavailable. Your wishlist is still saved.');return;}const text=api.inquiryText(wishlist);if(lastInquiry&&field.value.includes(lastInquiry))field.value=field.value.replace(lastInquiry,text);else if(!field.value.includes(text))field.value+=(field.value?'\n\n':'')+text;lastInquiry=text;document.querySelector('#inquiry select[name="interest"]').selectedIndex=0;document.querySelector('#form-status').textContent='Your '+wishlist.length+' saved destinations have been added to your enquiry draft. Complete your contact details below. Nothing has been sent.';document.querySelector('#inquiry').scrollIntoView({behavior:motion(),block:'start'});field.focus({preventScroll:true});announce('Your saved destinations have been added to the enquiry form.');};
function syncDialogAdd(){const b=modal.querySelector('.explorer-dialog-add');if(b){b.textContent=wishlist.includes(active)?'Added to My Journey ✓':'Add to My Journey +';b.setAttribute('aria-pressed',String(wishlist.includes(active)));}}
$('.explorer-detail').onclick=()=>{const p=api.places.find(p=>p.id===active);modal.querySelector('.explorer-dialog-content').innerHTML='<img class="explorer-dialog-image" src="'+esc(p.image)+'" alt="'+esc(p.alt)+'"><div class="explorer-dialog-copy"><p class="explorer-place-region">'+esc(p.region)+'</p><h3 id="explorer-detail-title">'+esc(p.name)+'</h3><p>'+esc(p.more)+'</p><h4>Make room for</h4><ul>'+p.attractions.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul><div class="explorer-dialog-note">'+esc(p.note)+'</div>'+(p.credit?'<p class="explorer-photo-credit">Photo: <a href="https://commons.wikimedia.org/wiki/File:Galle_Fort,_Sri_Lanka.JPG" target="_blank" rel="noopener noreferrer">Grayswoodsurrey</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · resized to WebP.</p>':'')+'<div class="explorer-dialog-actions"><button type="button" class="button explorer-dialog-add"></button><button type="button" class="explorer-dialog-done">Back to the island ↗</button></div></div>';syncDialogAdd();modal.querySelector('.explorer-dialog-add').onclick=()=>toggle(active);modal.querySelector('.explorer-dialog-done').onclick=()=>modal.close();modal.showModal();modal.scrollTop=0;};modal.querySelector('.explorer-dialog-close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});modal.addEventListener('close',()=>$('.explorer-detail').focus({preventScroll:true}));window.addEventListener('storage',e=>{if(e.key!==key)return;try{wishlist=api.cleanWishlist(JSON.parse(e.newValue||'[]'));renderWishlist();syncDialogAdd();}catch{}});
choose(active);renderWishlist();$('.explorer-save-note').textContent=canStore?'Your wishlist is saved in this browser.':'Your wishlist is available for this visit. Browser saving is unavailable.';
})();
